function HomeSceneLoadingPanel:Close()
    local arguments = UIModule.PopPage()
    
    if not isNull(arguments) and arguments.Count > 0 then
        xpcall(function()
            for i, v in support.list_ipairs(arguments) do
                cs_coroutine.yield_return(UIModule.OpenDialog(v.id, v))
            end
        end, function ()
            printError("[HomeSceneLoadingPanel] OpenDialog Error")
            cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
        end)
    else
        ---初始需要打包主界面
        cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.UIHomeView }))
    end

    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    
    CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.BelowNormal
        
    if not isNull(self.ActiveNode) then
        KTool.SetActive(self.ActiveNode.gameObject, true)
    end
    GameObject.Destroy(self.controller.gameObject, 1)
end

function HomeSceneLoadingPanel:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return HomeSceneLoadingPanel